-- Mauritania fourth preparatory year (mapped grade 10): 43 original
-- supplementary exercises across existing official-import title stubs.
-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"b92e33fd-2e46-4997-9766-559ca41fd547","n":1,"title":"فن الخطابة","passage":"تقوم الخطبة على مخاطبة جمهور معلوم بغرض محدد، وترتيب أفكار تؤيدها الحجج والانتقالات والخاتمة. مثال أصلي: يبدأ متحدث حديثًا عن ترشيد الماء بمشكلة واضحة ثم يقترح ممارسات قابلة للقياس؛ هذا ليس خطابًا تاريخيًا.","question":"ما العنصر الذي يقوي بنية الخطبة؟","correct":"فكرة واضحة وحجج مرتبة","wrong":["إخفاء المقصد","قافية بلا دليل","تكرار العنوان"],"practice":"خطط خطبة قصيرة من دقيقة تتضمن مقدمة وحجتين وخاتمة.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"b92e33fd-2e46-4997-9766-559ca41fd547","n":2,"title":"أفعال المدح والذم","passage":"يُستخدم «نِعْمَ» للمدح و«بِئْسَ» للذم في تراكيب لها أحكام نحوية خاصة؛ وتُحدد وظيفة الفاعل والمخصوص بالمدح أو الذم من بناء الجملة. مثال: «نعم الخُلُقُ الصدقُ» يحتاج ضبط التراكيب لا الاقتصار على معنى كلمة.","question":"أي فعل يستخدم غالبًا للمدح؟","correct":"نعم","wrong":["بئس","ليس","لن"],"practice":"كوّن مثالين صحيحين للمدح والذم، وبيّن الفاعل والمخصوص.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"b92e33fd-2e46-4997-9766-559ca41fd547","n":3,"title":"خطبة قس بن ساعدة الإيادي","passage":"تحتاج الخطبة المنسوبة إلى قس بن ساعدة الإيادي إلى نص محقق والتحقق من الروايات، ولا يجوز اختلاق جمل أو حكاية تاريخية عنه. مثال مستقل لمتحدث يسأل جمهوره سؤالًا بلاغيًا ثم يدعمه بحجة، لتدريب قراءة أسلوب الخطابة فقط.","question":"ما الشرط قبل نقل عبارة من خطبة منسوبة إلى قس بن ساعدة؟","correct":"الرجوع لنص موثق مع بيان المصدر","wrong":["تأليف قول مشابه","الاعتماد على اسم الخطيب","نقل شائعة"],"practice":"اقرأ النص المقرر من مصدر محقق واستخرج افتتاحًا وصورة وحجة بشواهد حقيقية.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"b92e33fd-2e46-4997-9766-559ca41fd547","n":4,"title":"صيغ التعجب","passage":"من صيغ التعجب القياسية «ما أفعَلَه!» و«أفعِلْ به!» عند استيفاء الشروط، مثل «ما أجملَ الأمانةَ!». لا تعرب كل «ما» تعجبية؛ فقد تستعمل للنفي أو الاستفهام حسب السياق.","question":"ما نوع «ما» في «ما أجمل الأمانة»؟","correct":"تعجبية في صيغة قياسية","wrong":["نافية قطعًا","حرف جر","أداة شرط"],"practice":"صغ مثالين للتعجب بصيغتين مختلفتين واضبطهما.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"b92e33fd-2e46-4997-9766-559ca41fd547","n":5,"title":"خطبة البتراء لزياد بن أبيه","passage":"دراسة خطبة البتراء تتطلب متنًا ثابتًا وسياقًا تاريخيًا ونقديًا قبل نسبة لفظ أو موقف لصاحبها. يمكن تدريب التحليل في خطاب مستقل يطرح مشكلةً ثم يهدد بتدابير إدارية؛ ويُدرس أثر الأسلوب دون تمجيد الإكراه أو نسبته للتاريخ.","question":"ما الأداة المناسبة لتحليل موقف الخطيب التاريخي؟","correct":"نص محقق وسياق المخاطب وألفاظ الحجة","wrong":["عنوان مشهور فقط","اختلاق شواهد","الحكم من اسم الخطيب"],"practice":"وثق شاهدًا من الخطبة المدرسية وحلل علاقة نبرة الكلام بغرض الإقناع.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"b92e33fd-2e46-4997-9766-559ca41fd547","n":6,"title":"فن الرسالة","passage":"تعتمد الرسالة على تحديد المخاطَب والغاية ووضوح ترتيب الكلام، وقد تختلف الرسالة الأدبية من الوظيفية في الصياغة والصورة. نموذج أصلي: يكتب طالب إلى أمين مكتبة لطلب تمديد الإعارة ويذكر السبب والموعد الجديد.","question":"ما المعلومة الضرورية في رسالة الطلب؟","correct":"المطلوب وسببه والمخاطب","wrong":["قافية شعرية","حوار طويل بلا غاية","تاريخ مختلق"],"practice":"اكتب رسالة وظيفية وأخرى أدبية حول موضوع واحد، ثم قارن النبرة والبناء.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"b92e33fd-2e46-4997-9766-559ca41fd547","n":7,"title":"رسالة عبد الحميد إلى أهله","passage":"عنوان رسالة عبد الحميد لا يحدد متنه أو مضمون النص المدرسي؛ يلزم الرجوع إلى مصدر أدبي موثق قبل نسبته إليه. مثال مستقل لمسافر يرسل رسالة أسرية منظمة تتضمن خبرًا وموقفًا ونصيحة غير منسوبة إلى رسالة تاريخية.","question":"ما الذي يثبت نوع الخطاب في نص رسالة؟","correct":"المرسل إليه والغرض والشواهد النصية","wrong":["العنوان وحده","اسم الكاتب وحده","الطول فقط"],"practice":"استخرج خطابًا مباشرًا وحجة من الرسالة الأصلية مع توثيق موضعها.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"b92e33fd-2e46-4997-9766-559ca41fd547","n":8,"title":"مهارة إنتاج نص حكائي","passage":"يتكون النص الحكائي من شخصية وهدف وعائق وأحداث متسلسلة تنتهي بحل أو تحول معقول. في مثال مستقل يفقد طالب ورقة مهمة ثم يتتبع خطواته ويجدها في المكتبة؛ لم تدخل شخصية خرافية لحل المشكلة دون سبب.","question":"ما الذي جعل حل العقدة منطقيًا في المثال؟","correct":"اتباع الشخصية خطوات البحث","wrong":["نهاية عشوائية","إلغاء السبب","اختفاء كل الشخصيات"],"practice":"اكتب قصة من سبع جمل تتضمن بداية وعقدة وحلًا واضح الصلة بأفعال الشخصية.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":1,"title":"الأغراض الشعرية","passage":"تختلف الأغراض بين الوصف والرثاء والمديح والفخر وغيرها، ولا يتحدد الغرض من القافية أو اسم الشاعر وحدهما. يحتاج التحليل إلى الأبيات والمخاطب والعاطفة، وقد تجتمع أغراض متعددة في قصيدة واحدة.","question":"ما الدليل الأوضح لتحديد غرض القصيدة؟","correct":"الأبيات الموثقة وسياق المخاطب","wrong":["حرف الروي وحده","اسم العصر فقط","عدد الأبيات"],"practice":"قارن غرضين شعريين بشاهد صحيح لكل منهما من مصدر محقق.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":2,"title":"أتعرف رسم الدار","passage":"تحتاج قصيدة «أتعرف رسم الدار» إلى نصها الصحيح لفهم المخاطب ودلالة رسوم المكان؛ ولا يجوز تأليف بيت ونسبته إلى الشاعر. مثال مستقل يزور فيه مسافر منزلًا قديمًا فيتأمل آثاره؛ وهو نثر تدريبي لا جزء من القصيدة.","question":"ما العنصر الأهم لتحليل دلالة الدار في القصيدة؟","correct":"وصف موثق من أبياتها","wrong":["العنوان وحده","مكان مختلق","توقع من القافية"],"practice":"وثق صورة للمكان من النص الأصلي واشرح علاقتها بالذاكرة أو العاطفة.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":3,"title":"التشبيه التمثيلي","passage":"يماثل التشبيه التمثيلي هيئةً منتزعة من عدة عناصر بهيئة أخرى؛ ومثال تدريبي مستقل: «تعاون الفريق في إنجاز العمل كأعضاء فرقة موسيقية ينسقون أدوارهم». يقوم وجه الشبه على انتظام العمل المشترك لا على لفظ مفرد.","question":"ما وجه الشبه في تمثيل الفريق بالفرقة الموسيقية؟","correct":"انتظام الأدوار والتعاون","wrong":["تشابه أسماء الأفراد","وجود قائد في النص فقط","تطابق المكان"],"practice":"أنشئ تشبيهًا تمثيليًا لهيئة من حياتك واشرح عناصر المشهدين.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":4,"title":"ليلة ذي دوران","passage":"لا تُستنتج تفاصيل ليلة «ذي دوران» أو الشاعر والمناسبة من العنوان وحده؛ نراجع النص المدرسي الموثق قبل تفسير صورة الليل ووجهة المخاطبة. نموذج أصلي يصور هدوء رحلة ليلية ومخاوف مسافر من الطريق دون محاكاة أبيات تاريخية.","question":"ما المطلوب قبل تحديد أحداث ليلة في قصيدة؟","correct":"الرجوع إلى النص والسياق الموثق","wrong":["اختلاق حادثة","التخمين من اسم المكان","حفظ عنوان فقط"],"practice":"استخرج قرينتين زمنيتين من القصيدة المقررة وفسر أثرهما على الشعور.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":5,"title":"الاستعارة التمثيلية","passage":"تُستعمل الاستعارة التمثيلية في سياق يُنقل فيه تركيب أو صورة كاملة إلى موقف شبيه بالعلاقة العامة، ولا تعادل مجرد حذف أداة التشبيه. يفيد الطالب من أمثال موثقة بعد شرح السياق الذي قيلت فيه دون نسبة مثل جديد للتراث.","question":"ما الذي ينتقل في الاستعارة التمثيلية؟","correct":"الصورة المركبة وعلاقتها بالموقف","wrong":["حرف واحد فقط","إعراب الفعل وحده","علامة الاستفهام"],"practice":"ابحث عن مثال تمثيلي موثق واشرح أصله والموقف الذي استُعمل فيه.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":6,"title":"بلغ سلامي","passage":"يحتاج نص «بلغ سلامي» إلى معرفة الصياغة الأصلية وقائلها والمخاطب الحقيقي قبل تفسير غرض الرسالة الشعرية. مثال مستقل يقول فيه مسافر لصديقه أن يبلغ أهله خبر سلامته، وهو نثر حديث لا شطر من النص.","question":"ما الذي يكشف مخاطب القصيدة؟","correct":"الضمائر والنداء وقرائن الأبيات","wrong":["العنوان وحده","أول حرف من القافية","الوزن وحده"],"practice":"حدد المخاطب والفكرة من بيت موثق ثم ناقش أثر أسلوب النداء أو الطلب.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":7,"title":"البحر الخفيف","passage":"تقوم إحدى صيغ الخفيف التام الأصلية على «فاعلاتن مستفعلن فاعلاتن» في كل شطر مع تغيرات عروضية. يتطلب الحكم على وزن بيت كتابته وفق المنطوق وفحص المقاطع بدل اعتماد عدد الكلمات.","question":"ما التفعيلة الوسطى في أصل الخفيف التام؟","correct":"مستفعلن","wrong":["فعولن","متفاعلن","مفاعلتن"],"practice":"قطّع بيتًا معروف المصدر على الخفيف وبين تفعيلاته في الشطرين.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":8,"title":"في وصف فرس","passage":"يمكن تحليل وصف الفرس من ألفاظ الحركة والقوة والصورة إذا ثبتت في أبيات الشاعر؛ لا يجوز صنع بيت ونسبته إلى نص «في وصف فرس». مثال مستقل يصف راويًا سرعة حصان وأثر وقع الحوافر دون محاكاة بيت تراثي.","question":"ما التفصيل الذي يدل على الحركة في المثال؟","correct":"وقع الحوافر","wrong":["اسم الشاعر","رقم الصفحة","حجم الديوان"],"practice":"استخرج لفظين من أبيات النص الأصلي يوضحان الحركة أو الوصف، مع تفسير أثرهما.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":9,"title":"بحر الرمل","passage":"يتكون الرمل التام في صورته الأصلية من تكرار «فاعلاتن» ثلاث مرات في كل شطر، مع صور الزحافات والعلل. التقطيع ينطلق من النطق الصحيح للشطر لا من الرسم الإملائي وحده.","question":"ما التفعيلة الأساسية لبحر الرمل؟","correct":"فاعلاتن","wrong":["فعولن","متفاعلن","مستفعلن"],"practice":"قطّع بيتًا من مصدر عروض موثوق يوضح الرمل مع تحديد أثر زحاف إن وجد.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":10,"title":"وصف بركة المتوكل","passage":"لتحليل «وصف بركة المتوكل» يلزم النص الشعري الموثق ومرجعه؛ لا تُفترض تفاصيل البركة أو تاريخها من العنوان. مثال مستقل يصف نافورة في ساحة مدينة ويناقش انعكاس الضوء على سطحها، ولا ينسب إلى شاعر.","question":"ما الذي يساعد على تحليل جمالية الماء في النص الأصلي؟","correct":"صورة لغوية صحيحة من الأبيات","wrong":["تخمين شكل البركة","خبر مختلق","اسم العنوان وحده"],"practice":"وثق شاهدًا لوصف الماء من القصيدة واشرح عناصر الصورة الحسية.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":11,"title":"بحر المضارع","passage":"بحر المضارع في العروض من البحور الأقل استعمالًا وله نسق تفعيلات معروف من «مفاعيلن فاعلاتن» في الصور المدروسة، ويتطلب فهم الزحافات والصورة المستعملة مراجعة مرجع عروض موثوق؛ لا يجوز تركيب بيت ونسبته لشاعر.","question":"أي تفعيلة تظهر في النسق المشهور للمضارع؟","correct":"مفاعيلن","wrong":["متفاعلن وحدها","فعولن وحدها","مستفعلن وحدها"],"practice":"استعن بمثال موثق للمضارع وقطّعه، مع تحديد الصورة العروضية المستعملة.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":12,"title":"أضرم الهم سحيرا","passage":"عنوان «أضرم الهم سحيرا» يوحي بصورة للهمّ والزمن لكنه لا يثبت القائل أو الموقف واللفظ الكامل. مثال أصلي «ظل متعلم قلقًا إلى الفجر ثم راجع خطته» مشهد نثري مستقل، يصلح لفهم التدرج الوجداني لا للاستشهاد به على القصيدة.","question":"ما التصرف السليم قبل نسبة صورة شعرية إلى قائل؟","correct":"التحقق من النص الكامل ومصدره","wrong":["توليد بيت من العنوان","تخمين اسم الشاعر","تبديل قافيته"],"practice":"اقرأ الأبيات الأصلية، واستخرج صورة زمنية وشعورية بشواهد صحيحة.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"6f252974-6985-42c5-ad49-e9056a476148","n":13,"title":"مهارة الشرح والتفسير","passage":"الشرح يوضح الألفاظ والعلاقات النحوية، بينما يناقش التفسير دلالة السياق وإمكان تعدد القراءات المنضبطة بالدليل. في نص مستقل «عاد الفتى مبتسمًا بعد انتهاء العمل» نصف الحال ونفسر تغير الموقف دون اختراع سبب لم يذكر.","question":"ما الذي يمنع التفسير من التحول إلى تخمين؟","correct":"الاستناد إلى قرائن نصية","wrong":["الاعتماد على الذوق وحده","إلغاء الشواهد","إضافة حادثة غير مذكورة"],"practice":"اشرح ثلاث عبارات من نص موثق، ثم قدم تفسيرين لأحدهما مع ما يؤيد كل قراءة.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"e7353237-e946-4868-8caf-0098b7aaf8b2","n":1,"title":"الأدب وعصوره","passage":"تتعدد تقسيمات تاريخ الأدب بحسب الأحداث السياسية والاجتماعية وتطور الأنواع، لكن لا يعني اسم العصر تشابه جميع نتاجه. يدرس الطالب نصوصًا مؤرخة في بيئات مختلفة ثم يحلل الاستمرار والتغير دون تعميم.","question":"ما الدليل الأفضل على تغير أسلوب أدبي عبر العصور؟","correct":"مقارنة نصين مؤرخين بشواهد","wrong":["اسم العصر وحده","قافية مشابهة","تاريخ غير موثق"],"practice":"أنشئ خطًا زمنيًا لأربع مراحل أدبية مع نص صحيح المصدر لكل مرحلة.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"e7353237-e946-4868-8caf-0098b7aaf8b2","n":2,"title":"الجملة الحالية","passage":"تأتي الجملة الحالية لتبيّن الهيئة في سياقها، مثل «دخل الطالبُ وهو يبتسمُ»؛ الجملة الاسمية «وهو يبتسم» في محل نصب حال مع رابط واضح. يختلف ذلك عن النعت حين يحدد الاسم صفة لازمة أو تابعة للتعريف.","question":"ما وظيفة «وهو يبتسم» في المثال؟","correct":"جملة حالية","wrong":["مفعول مطلق","مبتدأ مستقل بلا علاقة","أداة نهي"],"practice":"اكتب ثلاث جمل حالية متنوعة واذكر الرابط وصاحب الحال.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"e7353237-e946-4868-8caf-0098b7aaf8b2","n":3,"title":"المعلقات","passage":"المعلقات قصائد مشهورة في التراث القديم، لكن اختلاف الروايات وشروح المختارات يقتضي اعتماد ديوان محقق قبل نسبة نص أو سبب تسمية. يدرس الطالب المطلع والمضمون والبناء والعاطفة في القصيدة المدرسية الحقيقية، لا في أبيات مختلقة.","question":"ما الشرط اللازم قبل نقل بيت من معلقة؟","correct":"النص المحقق ونسبة الشاعر","wrong":["تأليف بيت على البحر","اعتماد الحكاية وحدها","اسم القصيدة فقط"],"practice":"اختر مطلعًا صحيحًا من معلقة موثقة وحلل صورة وغرضًا دون سرد روايات غير مسندة.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"e7353237-e946-4868-8caf-0098b7aaf8b2","n":4,"title":"الجملة النعتية","passage":"تأتي الجملة النعتية في سياقات نحوية معينة بعد نكرة مثل «رأيتُ طفلًا يحملُ كتابًا»؛ جملة «يحمل كتابًا» نعت للطفل في وجه التحليل المعروف. تُراجع الروابط والدلالة، فلا تعد كل جملة بعد اسم نعتًا تلقائيًا.","question":"ما وظيفة «يحمل كتابًا» في «رأيت طفلًا يحمل كتابًا»؟","correct":"جملة نعتية","wrong":["خبر إن","اسم مجرور","جواب قسم"],"practice":"اكتب مثالين لجملة نعتية وأخرى حالية وناقش الفرق.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"e7353237-e946-4868-8caf-0098b7aaf8b2","n":5,"title":"ظاهرة الصعلكة","passage":"تحتاج دراسة ظاهرة الصعلكة إلى مصادر تاريخية وشعرية موثقة مع التمييز بين الموقف الاجتماعي والرواية الأدبية، فلا يصح وصف جميع الأشخاص أو الشعراء بحكم واحد. مثال مستقل يبحث طالب سبب تنقل جماعة في بيئة صعبة مع بيان حدود الاستنتاج.","question":"ما الممارسة الصحيحة في دراسة ظاهرة اجتماعية قديمة؟","correct":"توثيق الروايات ومقارنة سياقاتها","wrong":["التعميم على الجميع","اختلاق تاريخ","الاعتماد على لقب فقط"],"practice":"قارن نصًا شعريًا صحيح النسبة بخبر تاريخي محقق وميز عناصر الأدب من الوقائع.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"e7353237-e946-4868-8caf-0098b7aaf8b2","n":6,"title":"المجاز المرسل","passage":"المجاز المرسل استعمال اللفظ في غير معناه الأصلي لعلاقة غير المشابهة مع قرينة، مثل إطلاق «الأيدي» للدلالة على أصحاب العمل في سياق واضح، ويجب توثيق المثال وتفسير العلاقة بدقة بدل اعتبار كل صورة استعارة.","question":"ما العلاقة التي تميز المجاز المرسل عن الاستعارة؟","correct":"علاقة غير المشابهة","wrong":["المشابهة دائمًا","تماثل الوزن","التطابق في القافية"],"practice":"ابحث عن مثال موثق للمجاز المرسل وحدد علاقته وقرينته.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"e7353237-e946-4868-8caf-0098b7aaf8b2","n":7,"title":"أقلي علي اللوم","passage":"تحتاج قصيدة «أقلي علي اللوم» إلى نص محقق لمعرفة سياق النداء والطلب والمخاطَب، ولا يجوز اختلاق بيت أو نسبة حالة نفسية للمتكلم من العنوان وحده. مثال أصلي يطلب فيه متحدث من صديقه التوقف عن اللوم المكرر بأسلوب مهذب.","question":"ما المطلوب لفهم غرض الطلب في القصيدة؟","correct":"قرائن الأبيات والسياق الموثق","wrong":["العنوان وحده","حكاية مبتكرة","اسم المخاطب تخمينًا"],"practice":"استخرج طلبًا موثقًا من القصيدة واشرح أثره في نبرة المتكلم.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"e7353237-e946-4868-8caf-0098b7aaf8b2","n":8,"title":"المجاز العقلي","passage":"يحدث المجاز العقلي عند إسناد الفعل إلى غير صاحبه الحقيقي لعلاقة مع قرينة، مثل «بنى المديرُ المدرسةَ» في سياق يقصد فيه أمره بالبناء وتخطيطه لا قيامه بكل العمل بيده. نميّز الإسناد المجازي من صورة التشبيه.","question":"ما وجه المجاز في «بنى المدير المدرسة» بالمعنى المذكور؟","correct":"إسناد العمل لمن أمر به","wrong":["وجود أداة تشبيه","تضاد كلمتين","تكرار حرف"],"practice":"اكتب مثالين للإسناد الحقيقي والمجازي مع شرح العلاقة والقرينة.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"e7353237-e946-4868-8caf-0098b7aaf8b2","n":9,"title":"مهارة تصميم عرض موضوع","passage":"يحتاج العرض المكتوب أو المرئي إلى سؤال مركزي وخطة مرتبة وشواهد موثقة ومقاطع متناسقة وخاتمة، مع ذكر المصادر. نموذج مستقل يقارن الطلاب وسيلتين لعرض نتائج قراءة، ويختارون الطريقة الأنسب للجمهور.","question":"ما الذي يضبط ترتيب العرض؟","correct":"سؤال أساسي ومحاور مترابطة","wrong":["نسخ معلومات بلا مصدر","إضافة صور عشوائية","إلغاء الخاتمة"],"practice":"جهز مخطط عرض من خمسة أجزاء مع عنوان ومثال وشاهد ومراجعة للمصادر.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"df59b89a-58d9-45c0-8563-abcd436a1070","n":1,"title":"مفهوم النقد","passage":"النقد الأدبي قراءة تتضمن وصف النص وفهم معانيه وتحليل لغته وبنائه وتقويم أثره بحجج. لا يكفي حكم «جميل» دون مثال. في نص ضاديوم الأصلي «صمتت النوافذ عند الغروب» تظهر صورة تشخيص، ويمكن تقويم علاقتها بجو السكون.","question":"ما الذي يحوّل الإعجاب إلى حكم نقدي مدعوم؟","correct":"شاهد فني مع تفسير أثره","wrong":["تكرار الإعجاب","اسم المؤلف فقط","عدد الصفحات"],"practice":"اكتب حكمين نقديين لفقرة أصلية من إنشائك، مع شاهد وتعليل لكل واحد.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"df59b89a-58d9-45c0-8563-abcd436a1070","n":2,"title":"الممارسة النقدية في العصر الجاهلي","passage":"تحتاج قراءة الأخبار النقدية في العصر الجاهلي إلى روايات موثوقة وسياق تاريخي، ولا يثبت من حكاية واحدة منهج جميع الشعراء والنقاد. يقارن الطالب معيارًا فنيًا ورد في مصدر محقق بشاهد شعري صحيح النسبة، مع التفريق بين الرواية والتحليل.","question":"ما الشرط لدراسة ممارسة نقدية تاريخية؟","correct":"مصدر موثق وشاهد أدبي صحيح","wrong":["حكاية مجهولة","اختلاق حكم ناقد","تعميم قصة واحدة"],"practice":"قدّم مثالًا نقديًا تاريخيًا موثقًا ووضح معياره وحدود دلالته.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"df59b89a-58d9-45c0-8563-abcd436a1070","n":3,"title":"اسم التفضيل","passage":"تأتي صيغة اسم التفضيل غالبًا على «أفعل» مع مراعاة شروط الاشتقاق، مثل «أوضح» في «شرحُ الطالب أوضحُ من شرح زميله»؛ نسأل عما تقع فيه المفاضلة ونراعي سلامة المعنى.","question":"ما اسم التفضيل في «شرحه أوضح»؟","correct":"أوضح","wrong":["شرحه","من","زميله"],"practice":"اكتب أربع جمل بأسماء تفضيل وحدد المفضّل والمفضّل عليه.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"df59b89a-58d9-45c0-8563-abcd436a1070","n":4,"title":"الممارسة النقدية في العصر الإسلامي","passage":"يرتبط تطور الأحكام النقدية بنصوص وروايات متعددة في مراحل عصر صدر الإسلام، ولا يجوز نسبة حكم نقدي إلى شخصية دينية أو شاعر بلا مصدر محقق. يطلب التدريب تحليل معيار وضوح الصورة في مثال مستقل دون نسبته للتاريخ.","question":"ما الإجراء السابق لنقل حكم نقدي تاريخي؟","correct":"التحقق من النص والقائل والسياق","wrong":["إضافة أقوال مناسبة","الاعتماد على اسم العصر","تخمين الشاهد"],"practice":"اختر خبرًا نقديًا موثقًا من مصدر أدبي، ثم افصل المعلومة عن تفسيرك.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"df59b89a-58d9-45c0-8563-abcd436a1070","n":5,"title":"التشبيه الضمني","passage":"قد يأتي التشبيه الضمني في تركيب لا يذكر طرفيه وأداته بصيغة التشبيه المباشر، بل يستدل بصورة ثانية على إمكان معنى أول. يحتاج التحليل العلاقة بين الحجتين لا مجرد ظهور أداة «مثل» في الجملة.","question":"ما الذي يميز التشبيه الضمني غالبًا؟","correct":"الاستدلال على الشبه من مضمون عبارتين","wrong":["وجود الكاف دائمًا","تطابق حروف الكلمات","غياب أي مقارنة"],"practice":"استخرج مثالًا موثقًا للتشبيه الضمني واشرح وجه العلاقة بين الصورتين.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"df59b89a-58d9-45c0-8563-abcd436a1070","n":6,"title":"الممارسة النقدية في العصر الأموي","passage":"تتأثر الآراء النقدية بالسياق الاجتماعي وتنوع الأغراض في عصر بني أمية، لكن لا يجوز اختلاق مجالس أو أحكام تاريخية. يدرس المتعلم مقطعًا نقديًا ثابت المصدر، ثم يقارن معاييره اللغوية بصورة شعريّة صحيحة.","question":"كيف نقوّم خبرًا عن نقد في العصر الأموي؟","correct":"بالتوثيق وتحليل المعيار والشواهد","wrong":["باسم القرن وحده","ببيت مولّد","بتعميم موقف شاعر"],"practice":"وثق ممارسة نقدية أموية مع شاهد وشرح معيار الحكم.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"df59b89a-58d9-45c0-8563-abcd436a1070","n":7,"title":"التشبيه المقلوب","passage":"في التشبيه المقلوب يُجعل المشبه به في موضع المشبه ادعاءً أن الصفة في الأصل أقوى عند الطرف الآخر، وقد يستخدم للتوكيد والمبالغة. لا يكفي تبادل الكلمات آليًا دون دلالة بلاغية مناسبة.","question":"ما الغرض الشائع من قلب طرفي التشبيه بلاغيًا؟","correct":"المبالغة في تأكيد صفة المشبه","wrong":["إلغاء المقارنة","إعراب المبتدأ","تحديد زمن الفعل"],"practice":"ابحث عن مثال صحيح للتشبيه المقلوب وناقش أثر القلب وحدود المبالغة.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"df59b89a-58d9-45c0-8563-abcd436a1070","n":8,"title":"عمود الشعر","passage":"«عمود الشعر» مصطلح نقدي تراثي تدور مباحثه حول معايير مثل شرف المعنى وصحة الألفاظ وأحكام النظم عند النقاد، لكن تفاصيل عناصره يجب أخذها من المصادر النقدية المحققة لا من تلخيص متخيل. يقارن المتعلم قراءة معيارية بقراءة حديثة.","question":"ما المصدر الأنسب لتحديد عناصر عمود الشعر؟","correct":"نص نقدي تراثي محقق","wrong":["قائمة مخترعة","عنوان الدرس وحده","قصيدة مجهولة"],"practice":"اختر معيارًا موثقًا من كتاب نقدي قديم وطبقه بشاهد صحيح على نص معروف.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"},{"cid":"6b329663-6a6a-4f54-9c41-d68ddbb9f7f8","unit":"df59b89a-58d9-45c0-8563-abcd436a1070","n":9,"title":"مهارة إنتاج نص حجاجي","passage":"يبني النص الحجاجي دعوى واضحة ويقدم أسبابًا وشواهد ويعرض اعتراضًا ثم ردًا منصفًا؛ لا يكفي تكرار الرأي بصياغات مختلفة. مثال مستقل يدافع فيه طالب عن تخصيص موعد أسبوعي للقراءة بدليل قابل للمناقشة.","question":"ما العنصر الذي يقوي الحجاج؟","correct":"الدليل والرد على الاعتراض","wrong":["المبالغة دون سبب","إخفاء الرأي المقابل","استبدال الشاهد بالشعار"],"practice":"اكتب فقرة حجاجية بدعوى وسببين وشاهد واعتراض ورد وخاتمة.","old":"DADYOOM_MR_G11_LITERARY_OFFICIAL"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='MR' AND c.id=r.cid
    AND g.grade_number=11 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G11_ARTS_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'MR_G11_ARTS_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'MR_G11_ARTS_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G11_ARTS_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_MR_G11_ARTS_ORIGINAL_39_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G11_ARTS_ORIGINAL_39_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_MR_G11_ARTS_ORIGINAL_39_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_MR_G11_ARTS_ORIGINAL_39_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'MR_G11_ARTS_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;